R=Path('benchmarks/dense500');ID='PMC12595977.1';S=json.loads((R/'sources'/f'{ID}.json').read_text());B={s['segment_id']:s['text'] for s in S['segments']};M=json.loads((R/'figure-assets'/f'{ID}.json').read_text());out=[]
rows=[
 ('FIG1','Extensive open wound photographed before staged wound coverage.','Single close clinical photograph of a long exposed limb wound on white draping. The wound bed occupies most of the frame, with glossy red/pink tissue, pale yellow-white surface bands and irregular margins. Two large black arrows point to the pale upper-right wound margin and an irregular recessed area below it. Intact skin borders portions of the long wound; no panel letters, scale, measurement ruler or acquisition timestamp are visible.','b00040','Initial debridement was performed for the wound (black arrows), which extended throughout the left thigh.','The caption documents initial debridement of the extensive left thigh wound; the photograph provides qualitative wound-bed appearance without measured size.','procedure_documentation'),
 ('FIG2','Negative pressure wound dressing over the limb wound.','Single photograph on blue draping. A long dark gray textured dressing covers the elongated wound region, overlain by a translucent wrinkled adhesive film. One outlined white arrow points to the covered foam region. A pale connector pad overlies the dressing at right-center and extends into tubing exiting toward the right. Surrounding skin is partly visible. No panel letters, pressure setting, ruler, device brand label or timestamp are legible.','b00041','The white arrow indicates the foam dressing of the VAC system covering the wound, which is overlaid with an adhesive drape to maintain negative pressure and facilitate fluid removal.','The caption identifies a VAC foam dressing with adhesive drape and dressing changes every three to four days. The case text describes two 12-day NPWT courses; this undated photograph does not distinguish which application is shown.','procedure_documentation'),
 ('FIG3','Wound bed after negative pressure treatment.','Single close photograph of an elongated uncovered limb wound resting on white draping. The broad bed is predominantly red/pink with a granular surface, darker red-brown streaks near the upper margin and an irregular concave recess at the right. One black arrow points toward the central-left red surface. Two outlined white arrows point to the upper-right and lower-right wound margins. Intact skin borders the wound; no panel letters, ruler or timestamp are visible.','b00042','The black arrow indicates healthy granulation tissue following vacuum-assisted closure (VAC) system therapy, while the white arrows indicate the undermined edges of the wound.','The caption identifies granulation tissue after VAC and undermined edges; the case text places an adequate granulation base before dermatome skin grafting. No exact wound depth or granulation percentage is derived from pixels.','treatment_response'),
 ('FIG4','Photograph of skin graft coverage over the limb wound.','Single clinical photograph on white draping. An elongated limb region is covered by a broad pink-brown sheet-like surface with visible transition lines and darker brown-red material along some edges. Orange-brown coloration appears over portions of the surface and nearby skin. Two outlined white arrows point toward the upper-left and lower-central parts of the coverage area. No lettered panels, ruler, numerical graft-integration label or timestamp are visible.','b00043','A split-thickness skin graft (white arrows) was performed to achieve definitive wound coverage.','The caption documents split-thickness graft coverage. The discussion separately reports 90% graft integration and approximately five-week wound coverage; neither value is a pixel measurement or an embedded image label.','procedure_documentation')]
def tag(value,basis='caption',sid=None,quote=None,cue=None,asdoc=None):return dict(value=value,as_documented=asdoc,basis=basis,visual_cue=cue,evidence=[{'segment_id':sid,'quote':quote}] if sid else [],certainty='clear')
