 out.append(dict(figure_id=fid,status='inspected',assets=[dict(url=asset['url'],sha256=asset['sha256'])],analysis=dict(visual=dict(figure_id=fid,general_description=gen,detailed_description=detail,panels=[p],limitations=lim),attribution=dict(figure_id=fid,assignments=[dict(panel=None,patient_ids=['p1'],scope='individual',subject='patient',evidence=[dict(segment_id='b00006',quote='The patient was a 42-year-old male'),dict(segment_id=sid,quote=B[sid])],rationale='Single index case, corresponding wound-management caption and case Figure reference explicitly link the photograph to this patient.')],limitations=[])),limitations=lim))
